// machines/plaits: lib/svf.c's band-pass loops, hand-written SISD kernels.
// Generated by lib/gen_svf_kernel.py; do not edit by hand.
//
// svf_bp_kernel(Svf *s, const float *in, float *out, int size, float *gain): out[i] = bp (gain null) or
//   out[i] += *gain * bp (svf_band_pass_add); in may be out. The state (state_1_, state_2_) goes back to s.
//   Bit-identical to selcc's code of the C loops (-DPL_SVF_C) (tests/plaits/test_svf_kernel.py).
//
// State on return: R0-R8, R12, I4 and the flags change; every other register is as on entry (R9-R11, R13-R15 saved
// above I7; I0, I1, M6, L0, L1, L4 pushed through R0, M6 = 1 and L0 = L1 = L4 = 0 set here). No SIMD.
// ABI: as the other kernels (lib/wavetable_sm.s).

.SECTION/PM seg_pmco;
.GLOBAL svf_bp_kernel.;
.COMPRESS;

svf_bp_kernel.:
    R0 = I0;
    DM(I7, M7) = R0;
    R0 = I1;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    M6 = 1;
    L0 = 0;
    L1 = 0;
    L4 = 0;
    I7=MODIFY (I7,-6)(NW);
    DM(1, I7) = R9;
    DM(2, I7) = R10;
    DM(3, I7) = R11;
    DM(4, I7) = R13;
    DM(5, I7) = R14;
    DM(6, I7) = R15;
    I4 = R4;                                            // s
    I1 = R8;                                            // in
    I0 = R12;                                           // out
    R13 = DM(0, I4);                                    // g
    R14 = DM(1, I4);                                    // r
    R15 = DM(2, I4);                                    // h
    R10 = DM(3, I4);                                    // state_1
    R11 = DM(4, I4);                                    // state_2
    R8 = DM(1, I6);                                     // size
    R0 = DM(2, I6);                                     // gain (pointer)
    R1 = 0;
    COMP(R8, R1);
    IF LE JUMP _svk_done;
    COMP(R0, R1);
    IF EQ JUMP _svk_plain;
    R12 = PASS R0;
    I4 = R12;
    R0 = 0;                                             // (DAG gap)
    R1 = 0;
    R2 = 0;
    R9 = DM(I4, M5);                                    // gain
    LCNTR = R8, DO _svk_e0 UNTIL LCE;
    R0 = DM(I1, M6);                                    // in[i]
    F1 = F14 * F10;                                     // hp = (in - r s1 - g s1 - s2) * h
    F1 = F0 - F1;
    F2 = F13 * F10;
    F1 = F1 - F2;
    F1 = F1 - F11;
    F1 = F1 * F15;
    F3 = F13 * F1;                                      // bp = g hp + s1
    F3 = F3 + F10;
    F10 = F13 * F1;                                     // s1 = g hp + bp
    F10 = F10 + F3;
    F2 = F13 * F3;                                      // lp = g bp + s2
    F2 = F2 + F11;
    F11 = F13 * F3;                                     // s2 = g bp + lp
    F11 = F11 + F2;
    F3 = F9 * F3;                                       // gain * bp
    R1 = DM(I0, M5);
    F1 = F1 + F3;
_svk_e0:
    DM(I0, M6) = R1;                                    // out[i] += gain * bp
    JUMP _svk_done;
_svk_plain:
    LCNTR = R8, DO _svk_e1 UNTIL LCE;
    R0 = DM(I1, M6);                                    // in[i]
    F1 = F14 * F10;                                     // hp = (in - r s1 - g s1 - s2) * h
    F1 = F0 - F1;
    F2 = F13 * F10;
    F1 = F1 - F2;
    F1 = F1 - F11;
    F1 = F1 * F15;
    F3 = F13 * F1;                                      // bp = g hp + s1
    F3 = F3 + F10;
    F10 = F13 * F1;                                     // s1 = g hp + bp
    F10 = F10 + F3;
    F2 = F13 * F3;                                      // lp = g bp + s2
    F2 = F2 + F11;
    F11 = F13 * F3;                                     // s2 = g bp + lp
    F11 = F11 + F2;
_svk_e1:
    DM(I0, M6) = R3;                                    // out[i] = bp
_svk_done:
    I4 = R4;                                            // s
    R0 = 0;                                             // (DAG gap)
    R1 = 0;
    R2 = 0;
    DM(3, I4) = R10;
    DM(4, I4) = R11;
    R9 = DM(1, I7);
    R10 = DM(2, I7);
    R11 = DM(3, I7);
    R13 = DM(4, I7);
    R14 = DM(5, I7);
    R15 = DM(6, I7);
    I7=MODIFY (I7,6)(NW);
    L4 = DM(1, I7);
    L1 = DM(2, I7);
    L0 = DM(3, I7);
    M6 = DM(4, I7);
    I1 = DM(5, I7);
    I0 = DM(6, I7);
    I12 = DM(M7, I6);
    JUMP (M14, I12) (DB);
    RFRAME;
    NOP;
